buy_code:
if (
    데이터길이 > {min_len}
    and {entry_start} <= 시분초 <= {entry_end}
    and 시가총액 <= {cap_max}
    and 당일거래대금 >= {day_money_min}
    and {rate_min} <= 등락율 <= {rate_max}
    and 전일동시간비 >= {prev_ratio_min}
    and 호가갭발생 == {gap_flag}
    and ((매도잔량1({book_window}) + 매도잔량2({book_window}) + 매도잔량3({book_window}) + 매도잔량4({book_window}) + 매도잔량5({book_window})) / (매수잔량1({book_window}) + 매수잔량2({book_window}) + 매수잔량3({book_window}) + 매수잔량4({book_window}) + 매수잔량5({book_window}) + {eps_qty})) <= {ask_bid_max}
    and (누적초당매수수량({flow_window}) / (누적초당매도수량({flow_window}) + {eps_qty})) >= {lift_ratio_min}
    and ((VI가격 - 현재가) / VI호가단위) >= {vi_avoid_ticks}
):
    self.Buy()

sell_code:
if (
    수익률 >= {take_hard}
    or 수익률 <= -{stop_hard}
    or 보유시간 >= {max_hold_sec}
    or (최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap})
):
    self.Sell()
